// A customer rates a resolved ticket once, 1 to 5. A second attempt is refused; the first rating stands.
// A score of 2 or below tells the owner by email; there's no one to tell if the ticket has no owner.
function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
  if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('score must be a whole number from 1 to 5');
  const t = getMyTicket(store, customer, id);
