'use strict';
// Nightly. Writes exports/agent-rating-summary.json: one row per agent who owns at least one ticket rated in the
// past seven days, with how many ratings they received and the average score.
const fs = require('node:fs');
const path = require('node:path');

const EXPORT_DIR = path.join(__dirname, '..', '..', 'exports');
const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function weeklyRatingSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
  const byOwner = new Map();
  for (const t of store.listTickets()) {
    if (t.rating_score == null || t.rated_at == null || !t.owner_id) continue;
    if (now.getTime() - new Date(t.rated_at).getTime() > WINDOW_DAYS * DAY) continue;
    const scores = byOwner.get(t.owner_id) || [];
    scores.push(t.rating_score);
    byOwner.set(t.owner_id, scores);
  }

  const rows = [...byOwner.entries()].map(([owner_id, scores]) => ({
    owner_id,
    ratings: scores.length,
    average: Math.round((scores.reduce((sum, s) => sum + s, 0) / scores.length) * 100) / 100,
  }));

  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'agent-rating-summary.json');
  fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
  return { file, rows };
}

module.exports = { weeklyRatingSummary, WINDOW_DAYS };
```

